const req = $('01 - Campaign Webhook').first().json.body || $('01 - Campaign Webhook').first().json || {};
const configRows = $('02 - Get Config').all().map(x => x.json);
const config = Object.fromEntries(configRows.map(x => [String(x.key || x.config_key || '').trim(), x.value || x.config_value || '']));
const patients = $('03 - Get Patients').all().map(x => x.json);
const offers = $('04 - Get Active Offers').all().map(x => x.json);
const conversations = $('05 - Get Conversations Log').all().map(x => x.json);

// 1. Timezone and Business Hours (10:00 AM - 7:00 PM Asia/Kolkata)
const tz = req.timezone || config.business_timezone || 'Asia/Kolkata';
const now = new Date();
const kolkataTimeStr = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: 'numeric', hour12: false }).format(now);
const currentHour = parseInt(kolkataTimeStr, 10);
const todayStr = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(now);
const isDryRun = Boolean(req.dry_run);

if (!isDryRun && (currentHour < 10 || currentHour >= 19)) {
  return [{ json: {
    success: false,
    _httpStatus: 400,
    error: 'Outbound campaigns are only permitted during business hours (10:00 AM to 7:00 PM ' + tz + ').',
    current_hour: currentHour,
    timezone: tz
  }}];
}

// 2. Daily Limit & Safety Cap (hard limit 25 per run)
const dailyLimit = Math.min(Number(config.daily_outbound_limit || 25), 50);
const hardRunLimit = 25;

// Count messages sent today from conversations
const sentToday = conversations.filter(row => {
  const rowTs = String(row.timestamp || '');
  return row.direction === 'outbound' && rowTs.startsWith(todayStr);
}).length;

const remainingToday = Math.max(0, dailyLimit - sentToday);
const runCapacity = Math.min(hardRunLimit, remainingToday);

// 3. Resolve active offer
const requestedOfferId = String(req.offer_id || '').trim();
const activeOffers = offers.filter(o => String(o.active).toUpperCase() === 'YES' || o.active === true);
const selectedOffer = (requestedOfferId ? activeOffers.find(o => String(o.offer_id).trim() === requestedOfferId) : null) || activeOffers[0] || {};

if (!selectedOffer.offer_id) {
  return [{ json: {
    success: false,
    _httpStatus: 400,
    error: 'No active offers available for campaign outreach.',
    requested_offer_id: requestedOfferId
  }}];
}

// 4. Validate customer_ids
let customerIds = Array.isArray(req.customer_ids) ? req.customer_ids.map(id => String(id).trim()).filter(Boolean) : [];
customerIds = [...new Set(customerIds)]; // deduplicate

if (customerIds.length === 0) {
  return [{ json: {
    success: false,
    _httpStatus: 400,
    error: 'Request must contain at least one valid customer_id.'
  }}];
}

const results = [];
const accepted = [];
let acceptedCount = 0;
const campaignId = 'CAMP-' + todayStr.replace(/-/g, '') + '-' + Math.random().toString(36).substring(2, 7).toUpperCase();

for (const id of customerIds) {
  const patient = patients.find(p => String(p.patient_id).trim() === id);
  if (!patient) {
    results.push({ patient_id: id, status: 'SKIPPED', reason: 'Customer ID not found in CRM database' });
    continue;
  }

  const optOut = String(patient.opt_out || '').toUpperCase() === 'YES';
  if (optOut) {
    results.push({ patient_id: id, status: 'SKIPPED', reason: 'Customer has opted out of communications' });
    continue;
  }

  const phoneDigits = String(patient.phone || '').replace(/\D/g, '');
  if (phoneDigits.length < 10) {
    results.push({ patient_id: id, status: 'SKIPPED', reason: 'Missing or invalid phone number' });
    continue;
  }

  if (String(patient.booking_status || '').toUpperCase() === 'BOOKED') {
    results.push({ patient_id: id, status: 'SKIPPED', reason: 'Customer already has a confirmed booking' });
    continue;
  }

  if (String(patient.conversation_state || '').toUpperCase() === 'HUMAN_REQUIRED') {
    results.push({ patient_id: id, status: 'SKIPPED', reason: 'Customer is currently escalated to human staff' });
    continue;
  }

  // Check if contacted today
  const contactedToday = conversations.some(c => String(c.patient_id).trim() === id && String(c.timestamp || '').startsWith(todayStr));
  if (contactedToday) {
    results.push({ patient_id: id, status: 'SKIPPED', reason: 'Customer was already contacted today' });
    continue;
  }

  // Check 7-day cooldown
  const lastOutbound = patient.last_outbound_at ? new Date(patient.last_outbound_at) : null;
  if (lastOutbound && (now - lastOutbound) < (7 * 24 * 60 * 60 * 1000)) {
    results.push({ patient_id: id, status: 'SKIPPED', reason: 'Customer within 7-day campaign cooldown window' });
    continue;
  }

  // Check capacity
  if (acceptedCount >= runCapacity) {
    results.push({ patient_id: id, status: 'SKIPPED', reason: 'Daily limit of ' + dailyLimit + ' recipients reached' });
    continue;
  }

  // Prepare outreach message
  const firstName = patient.first_name || 'there';
          const practiceName = config.practice_name || config.spa_name || 'our practice';
  const treatment = selectedOffer.treatment || selectedOffer.offer_name || 'special treatment';
  const price = selectedOffer.price ? '$' + selectedOffer.price : 'special rates';
  const validDate = selectedOffer.valid_until || 'this month';
          const message = `Hi ${firstName} 😊 It’s been a little while since we saw you at ${practiceName}. We have a returning-client ${treatment} available for ${price} through ${validDate}. Would you like me to send you the booking link?`;

  acceptedCount++;
  accepted.push({
    patient,
    phone: phoneDigits,
    message,
    campaign_id: campaignId,
    offer_id: selectedOffer.offer_id,
    timestamp: now.toISOString(),
    row_number: patient.row_number
  });
  results.push({ patient_id: id, status: 'QUEUED', reason: null });
}

const skippedCount = results.filter(r => r.status === 'SKIPPED').length;

return [{
  json: {
    success: true,
    campaign_id: campaignId,
    status: accepted.length > 0 ? 'QUEUED' : 'SKIPPED',
    requested: customerIds.length,
    accepted: accepted.length,
    skipped: skippedCount,
    daily_limit: dailyLimit,
    sent_today_before_run: sentToday,
    remaining_after_run: Math.max(0, remainingToday - accepted.length),
    offer_id: selectedOffer.offer_id,
    offer_name: selectedOffer.offer_name,
    results,
    accepted_recipients: accepted
  }
}];

const recipients = $input.first().json.accepted_recipients || [];
return recipients.map((r, i) => ({
  json: {
    conversation_id: 'CONV-' + r.patient.patient_id + '-' + Date.now() + '-' + i,
    patient_id: r.patient.patient_id,
    timestamp: r.timestamp,
    direction: 'outbound',
    message: r.message,
    message_id: 'MSG-' + r.campaign_id + '-' + r.patient.patient_id,
    intent: 'OUTREACH_SENT',
    state_before: r.patient.conversation_state || 'NEW',
    state_after: 'OUTREACH_SENT',
    response_time_seconds: '1.2',
    delivery_status: 'QUEUED',
    campaign_id: r.campaign_id,
    row_number: r.row_number,
    phone: r.phone
  }
}));
